// 遇敌槽增减与槽值（单一数据源）：world.tickEncounter 结算（累加/触发）与 view/drawWorld 小地图遇敌槽
// （clamp 与刻度分母、预警线、预警闪烁）同读此源——危险格 +10~18（dangerMin + [0,dangerVar) 随机）、喷泉 -25、其它可行走格 -6，
// 满 ENCOUNTER.full（=100）必遇敌。调「满槽 100 / 整体遇敌频率」只改这一处，绝无第二套口径；
// 预警线 ENCOUNTER.warn（=70）：小地图「⚠️ 危险逼近」高亮的读数临界值，同属于遇敌槽的口径——
// 此前与 full 一样游离在对象之外（v19.9 收口 full 时预留「另一语义」），现一并归入，调「何时亮危险预警」
// 也只改这一处。预警闪烁 ENCOUNTER.warnFlash（=330，单位 ms）：红色预警条的快闪开关周期
// Math.floor(Date.now()/warnFlash)%2，是遇敌槽读数可视反馈里最后一块裸奔数值（v19.9 收口 full、
// v19.12 收口 warn 后本家族最后一员——v19.12/v19.15 条目与 UI_PULSE_MS 注释都把它明确标为
// 「预警态闪烁 330ms」留白），现一并归入，调「⚠️ 危险逼近」快闪节奏也只改这一处。
// 数值逐字不变（满槽仍 100、预警线仍 70、预警闪烁仍 330），零遇敌/UI 回归。
const ENCOUNTER = { dangerMin: 10, dangerVar: 9, fountain: -25, calm: -6, full: 100, warn: 70, warnFlash: 330,
  // v23.31 遇敌槽昼夜修正（单一数据源·只调危险格步进）：夜晚（night）危险格步进 ×1.25 / 黎明（dawn）×0.85，
  // 白天/黄昏 ×1——world.tickEncounter 危险格分支同乘（Math.round 后入槽），H 页「遇敌槽 / 危险格」机制行
  // 与 README 数值速查「昼夜 / 时段」行同读此源；安全格 -6/喷泉 -25/槽满 100/预警线 70/快闪 330 逐字不动；
  // 无字回廊恒暗例外（curMap()==='gallery' 不乘修正，「被忘掉的地方没有晨昏」）；调修正只改本文件一处。
  phaseGauge: { day: 1, dusk: 1, night: 1.25, dawn: 0.85 } };

const CAVE_TREASURE = MAPS.cave.treasure;
const INN_PRICE = 10;

// v22.52 星井矿脉「矿车轨道」（新内容·世界景观·纯显示，承 v22.39 星砂车「名字物补脸」先例的收口）：
// 矿脉地图 v13.5 注释「轨道引导线贯穿——入口（井巫）→ 矿车区（车夫/试炼碑）→ 深处祭坛 → 中央水晶」，
// ASCII 里的 PATH '.' 格就是这条引导线——v22.39 立起的星砂车停在 (19,10) 矿场、车夫守着空气轨道：
// 轨道本体在 replaceTiles（PATH→CAVE）之后与世界画面岩地同色，一像素可见的轨道都没有（车夫「从前往
// 镇上拉星砂」拉的是看不到的轨道）。现把「轨道 = 矿脉图 PATH 格」作为单一数据源收口于此：逐行扫描
// MAPS.cave.rows 的 '.' 字符（35 格：西缘纵列 + 顶部横段 + 斜下引线 + 底部横段 + 南向短支，与地图
// 引导线逐格一致），改图自动跟随、轨道永不与地图漂移；view/drawWorld.js 的世界绘制共用（纯显示
// 零结算零存档：'.' 仍是 PATH→CAVE 可行走格，at()/SOLID/遇敌/开箱判定逐字不变，不进存档不设小地图
// 标记——轨道是矿脉的地貌不是决策信息，与星砂车/名字之门「无决策信息不设标」同口径）。
const CAVE_RAIL = (() => {
  const out = [];
  MAPS.cave.rows.forEach((row, y) => {
    [...row].forEach((ch, x) => { if (ch === '.') out.push([x, y]); });
  });
  return out;
})();

