  hunter:{name:'雾径猎手', mark:'hat', linesByStage:[
    { gate:null, lines:[
      ['雾径猎手：守这片林子大半辈子。泉水还在，','喝一口，忘了的力气会回来。歇够再往祭坛走。','[Enter] 继续'],
      ['雾径猎手：草丛毒蛇牙上带毒，被咬就一路失血。','腹地石心魔像会凝石甲——旧矿的守门人走丢了。','备好药水再走！ [Enter] 结束'],
    ]},
    { gate:'galleryOpen', lines:[
      ['雾径猎手：林子里的雾灵忽然安静了，像被什么唤走了。','你把回廊的门打开了？','[Enter] 继续'],
      ['雾径猎手：去吧。守林人守林，守灯人——','守名字。','[Enter] 结束'],
    ]},
  ], after:[
    ['雾径猎手：雾退了，林子亮了，泉水还是那口泉水。','毒蛇回了草丛，石心魔像重新变回石头。','守了大半辈子，头回见它这么安静。 [Enter] 继续'],
    ['雾径猎手：魔物是雾里长出来的。雾一散，','它们便像被领回家的记忆，各归各位。','看灯的人多了你一个，守林人心里亮堂。 [Enter] 结束'],
  ]},
  cartman:{name:'星砂车夫', mark:'lamp', lines:[
    ['星砂车夫：这洞从前往镇上拉星砂，喂那些记忆之灯。','洞窟领主霸了矿脉后，没运走的一车星砂和金银，','被碎石埋在矿车边上。 [Enter] 继续'],
    ['星砂车夫：你若击败洞窟领主，碎石坍落，','那车货会在祭坛左边显形。打完别急着走，','记得回头把箱子开了。 [Enter] 结束'],
  ], after:[
    ['星砂车夫：矿脉安静了。星砂不再发亮——','不是灭了，是被记起来了。','[Enter] 结束'],
  ]},
  clerk:{name:'守书记', mark:'hood', lines:[
    ['守书记：旧矿的账，我记了一辈子。石魔像本该是守门人——','石壳里封着矿脉的记忆。可它们如今在雾语林游荡，像丢了钥匙。','[Enter] 继续'],
    ['守书记：你若讨伐三尊石魔像，带回三份「石壳记痕」，','我替你读旧矿最后那页。去吧，雾语林里找它。','[Enter] 结束'],
  ], after:[
    ['守书记：旧矿最后那页读完了。星砂不发光的那天，','不是灭了——是被记起来了。账上又多了一个名字。','[Enter] 结束'],
  ]},
  guard:{name:'守名者', mark:'staff', lines:[
    ['守名者：这条回廊里躺的名字，都是「替别人记住了什么、','却没人记得他们」的人。碑不是刻给死者的——','是刻给还活着、却把名字弄丢的人看的。 [Enter] 继续'],
    ['守名者：再往东，残焰魔像守着窄道；尽头是初灯自己。','你若要去，先把图鉴翻完、把药水灌满。','回廊不记输家。 [Enter] 结束'],
  ], after:[
    ['守名者：初灯的名字……你带回来了。','我守着无字回廊守了一辈子，头一回看见','碑上有人能念出声。 [Enter] 继续'],
    ['守名者：去吧。名字被记住了的人，','雾就进不了他的梦。 [Enter] 结束'],
  ]},
  // 老矿工（v21.17 新 NPC·纯闲聊）：星井矿脉入口的「矿脉生存指南」——矿脉没有泉水/旅店（全图唯一无补给区），
  // 提示与地图事实逐字相符（dungeon FOUNTAIN 12,9 是最近免费恢复点；水晶 SB 需双徽记；CAVE_TREASURE 只在
  // 击败洞窟领主后显形）；linesByStage 按主线旗标分段揭示（承 sage/guard 同款无任务 NPC 模式），
  // trueBoss 后走 after 彩蛋（npcQuestPages 同源读取）。mark:'pick' 由 view/sprites.js drawNpcMark 程序化绘制。
  miner:{name:'老矿工', mark:'pick', linesByStage:[
    { gate:null, lines:[
      ['老矿工：头回来矿里？记住——这儿没有泉水，也没有旅店。','进矿前先回镇上把药水补满；雾语林营地那口泉，','是这附近最后一处免费的水。 [Enter] 继续'],
      ['老矿工：东边矿车区有辆旧车，车夫有活儿要托人。','至于中央的水晶——两枚徽记没凑齐之前，碰都不要碰。','[Enter] 结束'],
    ]},
    { gate:'bossDefeated', lines:[
      ['老矿工：灯芯讨回来了？镇上的灯，总算续上了。','可矿脉最深处那位，把最后一车星砂扣下了。','[Enter] 继续'],
      ['老矿工：击败它，埋在矿车边的货就会显形——','打完记得去东边那四条矿道翻一翻。','[Enter] 结束'],
    ]},
    { gate:'caveBoss', lines:[
      ['老矿工：领主倒了，矿里那声塌方响了一宿。','水晶亮了——两枚徽记凑齐，无字回廊的门开了。','[Enter] 继续'],
      ['老矿工：进回廊前，把药置办足。那里的雾，','连老子的矿灯都照不透。守名人在门口等你。','[Enter] 结束'],
    ]},
  ], after:[
    ['老矿工：矿洞里亮堂了。我挖了一辈子星砂，','头一回觉得，这灯是给所有记得路的人点的。','[Enter] 继续'],
    ['老矿工：雾散了，矿车还能跑十年。','下来歇歇脚，喝口井水再走。 [Enter] 结束'],
  ]},
  // 守碑人（v21.24 新 NPC·纯闲聊，无任务）：星井矿脉试炼碑旁——全图唯一「关键地标旁没有人在场守望」的空洞
  // （祭坛/水晶/回廊各有 NPC 指路，唯独试炼场只有 H 页与碑上刻字）；台词由 sentinelPages() 从
  // RUSH_RECOVER / RUSH_BASE_GOLD / RUSH_GOLD_PER_LV / RUSH_BOSSES 派生（试炼恢复/赏金/三连战阵容
  // 单一数据源，调试炼数值只改 data.js 一处、碑旁对话自动跟随；npcQuestPages 对函数型 lines 调用期求值，
  // 见 quests.js 一处分支），trueBoss 后走 after 彩蛋（npcQuestPages 同源读取）。
  sentinel:{name:'守碑人', mark:'staff', lines: sentinelPages, after:[
    ['守碑人：三场都胜了。碑光熄灭的那一瞬，我以为它会像镇上的灯一样亮一整夜——','结果它只是把三道刻痕照得更深了。 [Enter] 继续'],
    ['守碑人：刻痕深一分，忘掉的东西就少一分。','老朽守碑守到灯都亮了，值了。','去吧，记得把名字带回来。 [Enter] 结束'],
  ]},
  // 掌灯阿婆（v21.36 新 NPC·纯风味·潮灯镇水塘南岸）：讲旧故事的老人——linesByStage 按主线旗标选段
  // （默认/夺回灯芯 bossDefeated/回廊开启 galleryOpen，与巡灯人/雾径猎手同款既有机制、零新逻辑），
  // trueBoss 后走 after 彩蛋（npcQuestPages 同源读取）；无任务、零结算、零裸字面量。
  granny:{name:'掌灯阿婆', mark:'lamp', linesByStage:[
    { gate:null, lines:[
      ['掌灯阿婆：灯灭那晚，塘里的月亮也熄了。','雾是从井底爬上来的——可灯芯，怎么就去了林子里。','[Enter] 继续'],
      ['掌灯阿婆：雾里长出来的东西，都是被忘掉的旧事。','孩子，出门前把药水装满。','[Enter] 结束'],
    ]},
    { gate:'bossDefeated', lines:[
      ['掌灯阿婆：灯芯回来了，夜里的孩子哭，','不再说「找不到回家的路」了。','[Enter] 继续'],
      ['掌灯阿婆：可那影子，听说是旧灯卫变的。','守灯守到把自己……也守丢了。','[Enter] 结束'],
    ]},
    { gate:'galleryOpen', lines:[
      ['掌灯阿婆：回廊开了？被忘掉的名字，','都该回家看看了。','[Enter] 继续'],
      ['掌灯阿婆：替我看看……最旧那块碑上，','有没有一个叫「阿灯」的名字。','[Enter] 结束'],
    ]},
  ], after:[
    ['掌灯阿婆：你看这塘水，倒映着整座镇子的灯。','名字找回来了，灯也亮了。','[Enter] 继续'],
    ['掌灯阿婆：那孩子叫阿灯。','他被忘掉的名字，现在刻在你心里了。','[Enter] 结束'],
  ]},
  // 掌灯童（v22.11 新 NPC·纯风味）：无字回廊中段北侧（14,3）的提灯小孩——终局区的长廊太黑，
  // 她每天提着灯走一趟，说是「名字在等灯」；台词走既有 NPCS.lines 兜底 + trueBoss 后 after 彩蛋
