  // 与长者袍/商贩区分）；无任务、无顶标、零结算零存档。
  lampkid:{name:'掌灯童', mark:'lamp', lines:[
    ['掌灯童：这条回廊好黑呀，碑上也没有字。','可守名者爷爷说，名字都在这儿躺着呢。','[Enter] 继续'],
    ['掌灯童：我不认字，但我会提灯呀。','灯亮着，名字就找得到回家的路。','[Enter] 结束'],
  ], after:[
    ['掌灯童：昨天晚上，我提灯从头走到尾，','最旧那块碑，亮了！','[Enter] 继续'],
    ['掌灯童：名字都回家啦。','可我还是天天来——万一有谁想家，灯得在呀。','[Enter] 结束'],
  ]},
  // 说书人（v22.13 新 NPC·纯风味）：潮灯镇广场大灯南侧（16,9）的说书人——醒木一响讲《灯下潮声》，
  // 灯/井/雾/碑的世界观由他的段子串起（与镇民/掌灯阿婆的闲谈同脉，不涉任务/支线/结算）；台词走
  // 既有 NPCS.lines 兜底 + trueBoss 后 after 彩蛋（villager 同款机制、npcQuestPages 无待办任务回退
  // 直落，零新逻辑、零裸字面量）；mark:'fan' 由 view/sprites.js drawNpcMark 程序化绘制（折扇），
  // 造型复用 mwHunter（旅人斗篷身形，与同图镇长袍/商贩/镇民短衫区分）；无任务、无顶标、零结算零存档。
  teller:{name:'说书人', mark:'fan', lines:[
    ['说书人：醒木一响，说的正是《灯下潮声》——潮灯镇的灯啊，不是点的，是唤的。','要问唤灯的咒语？早没人记得啦。井底那口钟，还在替大家记着呢。','[Enter] 继续'],
    ['说书人：魔物从雾里来，名字被雾带走。','提着灯走夜路，影子就不怕丢了。等你手里有了灯，故事才轮到你讲。','[Enter] 结束'],
  ], after:[
    ['说书人：故事讲到头了——井不鸣了，灯全亮了，名字都回碑上了。','[Enter] 继续'],
    ['说书人：往后潮灯镇的日子，就是你写的那一页啦。','醒木一收，下回书……等你亲自来讲。','[Enter] 结束'],
  ]},
  // 锻灯师（v22.31 新 NPC·纯风味）：潮灯镇商店南侧草地角 (7,11) 的灯匠——镇子上所有灯的灯芯钩/油嘴/铜箍
  // 都是他打的：「灯记住路、人跟着灯走」的灯匠直白版世界观 + 出门补给（杂货铺药水/旅馆热汤）与
  // v21.40/v21.17/v22.22「出发前补给」同口径 + 圣光之剑的灯匠视角侧写（剑身封着的是一截黎明——与巡灯人
  // lore 同源不同面：一个讲它是什么，一个讲它是怎么打出来的）；台词走既有 NPCS.lines 兜底 + trueBoss 后
  // after 彩蛋（villager 同款机制、npcQuestPages 无待办任务回退直落，零新逻辑、零裸字面量）；
  // mark:'hammer' 由 view/sprites.js drawNpcMark 程序化绘制（铁锤，承 v22.13 fan / v22.27 qin 专属先例），
  // 造型复用 mwVillager（镇民短衫身形）；无任务、无顶标、零结算零存档。
  smith:{name:'锻灯师', mark:'hammer', lines:[
    ['锻灯师：镇上的灯，灯芯钩、油嘴、铜箍，全是我打的。','灯记住路，人跟着灯走——灯不好，人就容易在雾里丢。','[Enter] 继续'],
    ['锻灯师：进林子前，杂货铺的药水、旅馆的热汤都备齐。','我这儿只补灯，不补人。人，得靠你自己补。','[Enter] 结束'],
  ], after:[
    ['锻灯师：灯芯全亮回来了，连最旧的铜箍都不用换。','我打了半辈子灯，头回见灯比人先到家。','[Enter] 继续'],
    ['锻灯师：去吧，守灯人。铁锤归我管，灯归你管。','[Enter] 结束'],
  ]},
  // 拾菇人（v22.16 新 NPC·纯风味）：雾语林北环路蘑菇田西头 (15,2) 的采菇人——蘑菇是灯油，
  // 与 v22.14「菇香满仓」蘑菇线（宝箱 60% 蘑菇 / 酿造 2 株→1 瓶高级灵药 / 卖菇 10 金 / 灯长支线
  // 三株荧光）和「雾/灯」世界观同脉（雾语林此前只有雾径猎手一位 NPC，四图最空一格补第二个
