// 同读 XP_INIT（core.newGame 建档 / skillXpHint 旧档缺字段兜底）。调经验曲线只改 data.js 一处，
// 结算与预估绝无第二套口径（与 CHARGE_MULT / DROP_* / POTION_* 同一体系）
const XP_GROW = 1.42;
const XP_INIT = 20;

