// XP_INIT（首级所需经验）早已数据化，唯独开局金币 30 / 生命药水 3 仍在 core.js 裸奔；
// 想调开局家底（如加码到 50 金、或轻装开局 1 瓶药水）只改 data.js 一处，建档与任何
// 展示口径绝无第二套数值（与 INN_PRICE / BREW_GOLD / POTION_PRICE 同一「经济数据化」体系）
const START_GOLD = 30;    // 新档开局金币
