// `['day','dusk','night','dawn'][Math.floor(t/90)%4]` 此前以裸字面量 90 游离在 data.js 之外，view/hud
// 注释又自写一句「90 秒一档的昼夜标签」——判定与注释互不相关：想调昼夜节奏（如加快到 60 秒一档、
// 放慢到 120）要改判定 + 记得同步注释，还极易只改判定漏改注释，让「这个世界的昼夜跑多快」始终
