// 全图可开启宝箱总数由下方 chestTotal() 从 MAPS 逐图派生（潮灯镇 2 + 雾语林 3 + 星井矿脉 2+4(领主后显形)
// + 无字回廊 1 = 12；v21.19 加入回廊遗物宝箱后旧注释「11 个」脱节，本次数据化收口），访遍村落/林/矿
