// 精英「石心魔像」成长基准（单一数据源）：battle.eliteEncounter 生成、rules.codexStats/monReward 图鉴参考同读此表
// v21.51 数值平衡（攻击成长 3→2，推荐等级名副其实）：此前 atk [12,3]——Lv3 登场即 atk 21，
// 对推荐装备（铜剑+皮甲 def 13）的 Lv3 玩家（满血 59）一击均伤 29：均值两击 58 已是「贴线两击」，
// 含 ±10% 浮动上限 32×2=64 ≥ 59——满血硬打两发高飞拳直接被带走、连喝药窗口都没有；
// 40000 场蒙特卡洛单场死亡率 35.8%（中期模拟雾语林 10 场连刷死亡 14.7%、99% 凶手是它）——
// 与「⚠ 此敌有些棘手」（threat 1，v21.47 口径）和 v3.26「石甲机制怪不该同时是纯数值最强」
// 原则直接矛盾（它的招牌是石甲与 21 防铁壁，不是两拳超人；v20.9 残焰魔像校准的精英标尺是
// 「重击占满血 92%、满血可存活」，它的普攻两击却已越线）。现收为 [12,2]：Lv3 atk 18
// （均伤 23、浮动上限 25×2=50 < 59，满血两击可存活、三击才倒——玩家有喝药/防御窗口），
// 死亡率 35.8%→0.6% 而场均喝药 ≈1 瓶（威胁降级为「资源压力」而非「即死轮盘」）；
// def [15,2] 铁壁身份、hp [58,10]、报酬 [40,6]/[45,6]、ELITE_GATE_LV/ELITE_CHANCE、
// 石甲 acts 全部未动——它仍是雾语林最难啃的遭遇，只是不再秒人。属性遇敌时现算，旧档零迁移。
const ELITE_GOLEM = {name:'石心魔像',hp:[58,10],atk:[12,2],def:[15,2],xp:[40,6],gold:[45,6],color:'#6b8cb0'};

function withSpecies(enemy) {
  const species = SPECIES[enemy.name] || {};
  return Object.assign({}, species, enemy, {
    weak: enemy.weak || species.weak,
    resist: enemy.resist || species.resist,
    draw: enemy.draw || species.draw,
    acts: enemy.acts || species.acts,
    phase2: enemy.phase2 || species.phase2,
    tag: enemy.tag || species.tag,
  });
}

// 三强敌基础数值（单一数据源）：主线 BOSS / CAVE_BOSS / TRUE_BOSS 与其试炼场复刻版（RUSH_BOSSES）
// 的 name/hp/hpMax/atk/def/color 六项同读此源——此前 hp:140·atk:15·def:6 这类数值在主线 Boss 定义与
// RUSH_BOSSES 各写一份互不相关：想调强敌兵力（如把幽冥魔王 atk 提到 17）要改两处，还极易只改主线漏改试炼，
// 两处强度悄然脱钩。试炼版仅覆盖 xp/gold/isRush（试炼不给金币、经验另计少给），兵力数值与主线逐字同源、永不漂移。
// v20.6 数值平衡（Boss 战力与 ⚠Lv 警告脱节修复）：原 140/15/6、110/16/10、260/22/13 沿袭单文件时代（技能
// 尚未分化：火焰斩 1.8 / 冰霜击 2.2 / 雷鸣 2.8 / 陨石术 4.2 + 弱点×1.35），而玩家 atkMax 随等级线性
// 7+2·lv——实测（rules.skillEstimate 真实预览）在各自⚠Lv（8/7/12）推荐装备下 陨石术 期望伤害 305/263/415，
// 一击即秒 Boss（140/110/260），且 0 药/裸打胜率 100%（20k 蒙特卡洛，镜像 enemyAct/attackMove 公式）：
// 「⚠Lv.X 推荐」全游戏信息透明体系与实际战力完全脱节，三场主线 Boss 战沦为单键演出。本次把三 Boss 基准
// 抬到「⚠Lv 推荐装备下 2.7-3.0 回合的正面战、无药也有 94-100% 胜率但 phase2 重击（×2.3）威胁明显、
// 低于⚠Lv 2 级（如 Lv5-6 打魔王）胜率骤降」的档位——数值来源为 12 组×6000 次蒙特卡洛参数扫描
// （真实 actions 表/石甲/回血/phase2/防御反击公式镜像）：魔王 420/23/13、领主 380/25/15、神 700/33/19。
// 三 Boss phase2 重击对 ⚠Lv 满血玩家仍可存活（魔王76/领主81/神92 vs 上限血量 94/87/122），低于推荐
// 等级则可能一击致死——「该练到多少级再来」有了真实后果；试炼三连战（同源）Lv11 约 42% / Lv12 约 100%
// 通关（明智打法），仍是全游戏最重考验。xp/gold/phase2/acts/掉落/成就/剧情逐字不动，图鉴/帮助页/威胁预警
// 全部直读本表自动跟随（rules.BOSS_DEFS / threatWarn / monReward 同源）。
const BOSS_BASE={name:'幽冥魔王',hp:420,hpMax:420,atk:23,def:13,color:'#a03fd9'};
const CAVE_BOSS_BASE={name:'洞窟领主',hp:380,hpMax:380,atk:25,def:15,color:'#3f6b9f'};
const TRUE_BOSS_BASE={name:'终焉之神',hp:700,hpMax:700,atk:33,def:19,color:'#f0c040'};

const BOSS=withSpecies({...BOSS_BASE,xp:150,gold:300,isBoss:true,bossHpMax:BOSS_BASE.hpMax});
//          ↑ bossHpMax 由 BOSS_BASE.hpMax 推导（单一数据源）：v18.9 收口主线/试炼兵力时此值以裸 140 留存、
//          全库亦无任何读取方（仅 isBoss 驱动主线判定），是 BOSS_BASE 家族最后一处与真源脱钩的残留字面量——
//          调幽冥魔王最大 HP 只需改 BOSS_BASE.hpMax，bossHpMax 自动跟随；行为逐字不变（现两值同为 140）
const CAVE_BOSS=withSpecies({...CAVE_BOSS_BASE,xp:120,gold:200,isElite:true,isCaveBoss:true});
const TRUE_BOSS=withSpecies({...TRUE_BOSS_BASE,xp:400,gold:600,isTrue:true,isElite:true});
// 无字回廊中段精英（Fire Golem CC0 素材）：双徽记开门后的守门考验
// v20.9 数值平衡（走廊精英战力与「终局区」标签脱节修复）：此前固定 170/19/12 沿袭 v13.5 旧值——当玩家
// 带着双徽记、圣光之剑与龙鳞甲（走廊推荐装备）于 Lv10-11 进入时，走廊 zone 缩放后的普通怪（石魔像 147/36/24、
// 雾灵 103/37/17、骷髅兵 120/36/18）无论攻击、防御都全面高于这位「守门精英」；实测普通怪普攻对 Lv10 玩家造
// 34-38 伤害，而残焰魔像仅 2 点，且陨石术 378 伤害可一击秒杀（1 回合结束），守门战沦为演出。本次将兵力抬升到
// 「走廊精英」档位：340/44/28——高于同图 Lv11 zone 缩放后的普通怪（hp/def/atk 均高出一截），整体战力远低于
// 终焉之神（700/33/19，HP 仅约其一半），奖励 130xp/260 金、任务链、火焰弱点/精英标签等全部不变。Lv10 推荐装备下重击约 99
// 点（占满血 108 的 92%，满血可存活、低血需防御/用药），陨石术+普攻约 2 回合击杀；Lv9 以下/未换毕业装会
// 承受真实压力，与 v20.6 Boss 战力修复同一「⚠Lv 推荐等级必须名副其实」原则。
const EMBER_GOLEM=withSpecies({name:'残焰魔像',hp:340,hpMax:340,atk:44,def:28,xp:130,gold:260,color:'#e07a3f',isElite:true});

const RUSH_BOSSES=[
  withSpecies({...BOSS_BASE,xp:60,gold:0,isRush:true}),
  withSpecies({...CAVE_BOSS_BASE,xp:60,gold:0,isRush:true}),
  withSpecies({...TRUE_BOSS_BASE,xp:90,gold:0,isRush:true}),
];

// 试炼推荐等级（v21.46 新增·单一数据源）：三连战阵容读 RUSH_BOSSES，各关推荐等级与祭坛 ⚠Lv /
// enemyLv / 碑上阵容标签同读 SPECIES[].lv（真身/普通同名归一）——试炼是全游戏唯一「战前知识中枢未标
// 推荐等级」的最重挑战（v20.6 实测 Lv11 约 42% / Lv12 约 100% 通关，此前玩家只能从碑上阵容末位
// 「终焉之神Lv12」自行推断）；现 max(...) 派生为显式「建议Lv.N」（当前 8/7/12 → 12），守碑人台词 /
// 试炼碑标签 / H 页三端同读，调任一 Boss 的 lv 只改 SPECIES 一处、各方自动跟随，零裸字面量。
const RUSH_REC_LV = Math.max(...RUSH_BOSSES.map(b => (SPECIES[b.name] && SPECIES[b.name].lv) || 1));

// 守碑人台词（v21.24）：由试炼数值唯一真源派生——RUSH_RECOVER（关间恢复比例）、RUSH_BASE_GOLD /
// RUSH_GOLD_PER_LV（通关赏金公式，与 rules.rushReward 同式）、RUSH_BOSSES（三连战阵容，与战斗横幅
// 「第 N/3 关」、帮助页「试炼三连战」同源）；调试炼数值只改本文件对应常量一处，碑旁对话自动跟随，
// 绝无第二套口径（与 HELP_PAGES 派生同族）。调用期求值（npcQuestPages 对函数型 lines 分支），
// 模块顶层零副作用；hero 可为空（按 Lv.1 展示）。
function sentinelPages(hero) {
  const names = RUSH_BOSSES.map((b) => b.name);
  const hpPct = Math.round(RUSH_RECOVER.hp * 100);
  const mpPct = Math.round(RUSH_RECOVER.mp * 100);
  const lv = Math.max(1, (hero && hero.level) || 1);
  const reward = RUSH_BASE_GOLD + lv * RUSH_GOLD_PER_LV;
  return [
    [
      `守碑人：这方石碑比矿脉里的石头磨得还亮——三道刻痕：${names.join('、')}。`,
      `碑光在每胜一关的间隙，替你恢复 ${hpPct}%HP/${mpPct}%MP；三关尽破，赏金 ${reward} 金（随你等级水涨船高）。`,
      `这碑的阵仗，是按 ${RUSH_REC_LV} 级刻的——没到 ${RUSH_REC_LV} 级，碑光可护不住你。`,
      '老朽守在碑旁，只记一句：先凑齐两枚徽记，碑才会醒——细则都在 H 页「试炼进阶」里。',
      '[Enter] 继续',
    ],
    [
      `守碑人：那三位的招数，碑上都刻着——${names[0]}血过半现真身；${names[1]}石甲加身；${names[2]}入祸乱形态后，治愈术会被封印。`,
      '灵药省着点：碑光恢复的是血和蓝，不是你的药瓶。去吧，打完回来陪老朽喝一盏。',
      '[Enter] 结束',
    ],
  ];
}

// 试炼碑未解锁提示（v21.26 信息透明·进度即时，承 v19.72 宝箱进度 / v21.22 宝箱双口径同主线）：onTrialStele
// 在未集齐双徽记时调用——此前只有一句静态「…试炼碑需要两枚徽记（幽冥魔王 + 洞窟领主）。」，玩家先击败
// 其中一位 Boss 后再踩碑，提示依旧不告诉他「已经拿到几枚、还差哪一枚」（得翻 I 状态页或 J 日志自查）；
// 现按 hero.bossDefeated / hero.caveBoss 实时派生，两位 Boss 名读 BOSS / CAVE_BOSS 单一数据源（调名只改
// 一处），0 枚时输出与原文案逐字一致（零显示变化），1 枚时指明已得【X】与所差【Y】并附 (1/2) 实时计数。
// 纯函数零副作用，双徽记已集齐时返回 ''（调用方 startRush 分支不引用）。
function trialSteleHint(hero) {
  const have = [];
  if (hero && hero.bossDefeated) have.push(BOSS.name);
  if (hero && hero.caveBoss) have.push(CAVE_BOSS.name);
  if (have.length === 0) return '…试炼碑需要两枚徽记（' + BOSS.name + ' + ' + CAVE_BOSS.name + '）。';
  if (have.length === 2) return '';
  const miss = have[0] === BOSS.name ? CAVE_BOSS.name : BOSS.name;
  return '…还差一枚徽记：你已得【' + have[0] + '】的徽记，去击败【' + miss + '】吧。（' + have.length + '/2）';
}

