  // side_bone 同一「讨伐采集型支线」模式（无 unlockOn → 从开局即 offer，保留完整接取流程，
  // 承 side_ember 同款），阈值单一数据源 GRAIN_GOAL（判定/进度/目标文案/接取对话同读），
  // 奖励 50 金 + 1 生命药水——介于 side_mist（60 金+药水）之下、与开荒期档次匹配；active 页按
